import{_ as r,C as s,c as n,o as l,a3 as o,G as a}from"./chunks/framework.Dokpd4od.js";const w=JSON.parse('{"title":"Putaway rules","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/routes/putaway-rules.md","filePath":"master/supply-chain/inventories/routes/putaway-rules.md","lastUpdated":1791902625000}'),i={name:"master/supply-chain/inventories/routes/putaway-rules.md"};function u(c,e,d,h,g,p){const t=s("ImagePopup");return l(),n("div",null,[e[0]||(e[0]=o('<h1 id="putaway-rules" tabindex="-1">Putaway rules <a class="header-anchor" href="#putaway-rules" aria-label="Permalink to &quot;Putaway rules&quot;">​</a></h1><p>A putaway rule tells Aureus where to store goods when they arrive. Without a rule, goods go to the default destination of the document. With a rule, a product or category is sent to a chosen shelf or zone.</p><blockquote><p><strong>In simple words:</strong> When this product arrives here, store it over there.</p></blockquote><p>Open it from <code>Inventory → Configurations → Warehouse Management → Putaway Rules</code>.</p><div class="warning custom-block"><p class="custom-block-title">Gate</p><p>Needs <code>Inventory → Settings → Manage Warehouses → Locations</code> and <code>Multi Steps Routes</code> on. A <strong>Storage Category</strong> is optional. Create one under <code>Configurations → Storage Categories</code>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows <strong>When Product Arrives In</strong>, <strong>Product</strong>, <strong>Product Category</strong>, <strong>Store To</strong> and <strong>Sub Location</strong>. It has tabs <strong>All</strong> and <strong>Archived</strong>. Each row has only <strong>Edit</strong> and <strong>Delete</strong> links.</p>',7)),a(t,{src:"/images1/inventory/put_list.png",alt:"Putaway Rules list with one rule for Camping Hammock stored to WH/Stock/Shelf A"}),e[1]||(e[1]=o('<h2 id="create-a-putaway-rule" tabindex="-1">Create a putaway rule <a class="header-anchor" href="#create-a-putaway-rule" aria-label="Permalink to &quot;Create a putaway rule&quot;">​</a></h2><ol><li>Click <strong>New Putaway Rule</strong>. The <strong>Create Putaway Rule</strong> window opens.</li><li>Fill in the fields.</li><li>Click <strong>Create</strong>.</li></ol>',2)),a(t,{src:"/images1/inventory/put_form.png",alt:"Create Putaway Rule window with When Product Arrives In WH/Stock, Product Camping Hammock and Store To WH/Stock/Shelf A"}),e[2]||(e[2]=o('<ul><li><strong><em>Company:</em></strong> required. Defaults to your company.</li><li><strong><em>When Product Arrives In:</em></strong> required. The location where goods land, for example <code>WH/Stock</code>.</li><li><strong>Product:</strong> shows <strong>All Products</strong> until you pick one.</li><li><strong>Product Category:</strong> shows <strong>All Categories</strong> until you pick one.</li><li><strong>Storage Category:</strong> limits the rule to locations of that category.</li><li><strong><em>Store To:</em></strong> required. The final shelf. The list shows only the children of the arrival location. For example, <strong>WH/Stock/Shelf A</strong> appears after you choose <code>WH/Stock</code> as the arrival location.</li><li><strong><em>Sub Location:</em></strong> required. Default is <strong>No</strong>. Other choices are <strong>Last Used</strong> and <strong>Closest Location</strong>.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Camping Hammocks should go to <code>WH/Stock/Shelf A</code>.</p><ol><li>Create locations <code>WH/Stock/Shelf A</code> as a child of <code>WH/Stock</code>. See <a href="./../warehouses/locations.html">Locations</a>.</li><li>Create a rule: arrives in <code>WH/Stock</code>, product Camping Hammock, store to <code>WH/Stock/Shelf A</code>.</li><li>Receive hammocks. When the transfer into stock is validated, the goods are placed on Shelf A.</li></ol><h2 id="putaway-vs-routes" tabindex="-1">Putaway vs routes <a class="header-anchor" href="#putaway-vs-routes" aria-label="Permalink to &quot;Putaway vs routes&quot;">​</a></h2><p>A route decides which steps happen. A putaway rule decides the final shelf inside the last step.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Routes overview</a></li><li><a href="./routes-and-rules.html">Routes and rules</a></li><li><a href="./../warehouses/locations.html">Locations</a></li><li><a href="./../warehouses/storage-categories.html">Storage categories</a></li></ul>',8))])}const f=r(i,[["render",u]]);export{w as __pageData,f as default};
